            elif direction == 'right':
                ni, nj = i+direction_x[3], j+direction_y[3]
            elif direction == 'up':
                ni, nj = i+direction_x[0], j+direction_y[0]
            else:
                ni, nj = i+direction_x[1], j+direction_y[1]
        return ni, nj, direction

    for steps in steps:
        for _ in range(steps[0]):
            i, j = dfs(i,j,steps[2])
            if _ + 1 == steps[0]:
                steps[1] -= 1
                steps = steps[1:]+[steps[0]-_]
    return output

